const MANAGED_HEADER: &str =
    "# Do not edit this file manually! It will be overwritten by Negroni/Patroni.";

static TMP_COUNTER: AtomicU64 = AtomicU64::new(1);

/// Crash-safe atomic file writer enforcing `AGENTS.md` §4.3:
/// 1. Creates a sibling `.tmp` file in the same directory with restricted permissions (`mode`),
/// 2. Writes `contents` and calls `File::sync_all()`,
/// 3. Atomically replaces `target` via `std::fs::rename`,
/// 4. Calls `File::sync_all()` on the parent directory file descriptor.
pub fn atomic_write_file(target: &Path, contents: &[u8], mode: Option<u32>) -> Result<(), PgError> {
    let parent = target.parent().ok_or_else(|| {
        PgError::ConfigValidation(format!(
            "target path '{}' has no parent directory",
            target.display()
        ))
    })?;
    fs::create_dir_all(parent).map_err(|source| PgError::Io {
        context: format!("creating parent directory '{}'", parent.display()),
        source,
    })?;

    let file_name = target
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("config");
    let seq = TMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let tmp_path = parent.join(format!(
        ".negroni.{file_name}.{}.{seq}.tmp",
        std::process::id()
    ));

    let effective_mode = mode.unwrap_or(0o600);
    let mut opts = OpenOptions::new();
    opts.write(true).create(true).truncate(true);
    #[cfg(unix)]
    {
        opts.mode(effective_mode);
    }

    let write_result = (|| -> Result<(), std::io::Error> {
        let mut tmp_file = opts.open(&tmp_path)?;
        #[cfg(unix)]
        {
            tmp_file.set_permissions(fs::Permissions::from_mode(effective_mode))?;
        }
        tmp_file.write_all(contents)?;
        tmp_file.sync_all()?;
        drop(tmp_file);
        fs::rename(&tmp_path, target)?;
        sync_directory(parent)?;
        Ok(())
    })();

    if let Err(source) = write_result {
        let _ = fs::remove_file(&tmp_path);
        return Err(PgError::Io {
            context: format!("atomically writing '{}'", target.display()),
            source,
        });
    }

    Ok(())
}

pub fn sync_directory(dir: &Path) -> Result<(), std::io::Error> {
    let dir_fd = File::open(dir)?;
    dir_fd.sync_all()
}

/// Preserves an existing DBA-authored `$CONFIG_DIR/postgresql.conf` as `postgresql.base.conf`
/// before Negroni writes its managed `postgresql.conf`. Returns `Ok(true)` when a baseline file
/// exists (either newly preserved or previously saved).
pub fn ensure_postgresql_base_conf(config_dir: &Path) -> Result<bool, PgError> {
    let base_conf = config_dir.join("postgresql.base.conf");
    if base_conf.exists() {
        return Ok(true);
    }

    let pg_conf = config_dir.join("postgresql.conf");
    if !pg_conf.exists() {
        return Ok(false);
    }

    let existing = fs::read_to_string(&pg_conf).map_err(|source| PgError::Io {
        context: format!("reading '{}'", pg_conf.display()),
        source,
    })?;

    if existing.lines().any(|l| l.trim() == MANAGED_HEADER) {
        return Ok(false);
    }

    fs::rename(&pg_conf, &base_conf).map_err(|source| PgError::Io {
        context: format!(
            "preserving '{}' -> '{}'",
            pg_conf.display(),
            base_conf.display()
        ),
        source,
    })?;
    sync_directory(config_dir).map_err(|source| PgError::Io {
        context: format!("syncing directory '{}'", config_dir.display()),
        source,
    })?;
    Ok(true)
}

/// Escapes a string value as a safe single-quoted PostgreSQL `postgresql.conf` literal,
/// rejecting NUL bytes or newlines in GUC identifiers to prevent configuration injection.
pub fn format_pg_conf_kv(key: &str, value: &str) -> Result<String, PgError> {
    if key.is_empty()
        || !key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'.')
    {
        return Err(PgError::ConfigValidation(format!(
            "invalid PostgreSQL GUC identifier '{key}'"
        )));
    }
    if value.contains('\0') {
        return Err(PgError::ConfigValidation(format!(
            "NUL byte forbidden in GUC '{key}'"
        )));
    }
    let escaped = value.replace('\'', "''").replace('\n', "\\n");
    Ok(format!("{key} = '{escaped}'"))
}

/// Splits `"host:port"` (`postgresql.listen` or `connect_address`) into `(listen_addresses, port)`.
pub fn parse_listen_host_port(listen: &str) -> (String, u16) {
    if let Some((host, port_str)) = listen.rsplit_once(':')
        && let Ok(port) = port_str.trim().parse::<u16>()
    {
        let cleaned_host = host.trim().trim_matches(['[', ']']);
        let addr = if cleaned_host == "0.0.0.0" || cleaned_host == "::" || cleaned_host.is_empty() {
            "*".to_owned()
        } else {
            cleaned_host.to_owned()
        };
        return (addr, port);
    }
    ("*".to_owned(), 5432)
}

/// Converts a `postgres://` URI or libpq keyword-value string into a libpq keyword=value
/// `primary_conninfo` string carrying `application_name` and (on PG 17–18 when `require_dbname`
/// is set for `slotsync`) an explicit `dbname` parameter.
///
/// # Examples
///
/// ```
/// use negroni_pg::config_writer::render_primary_conninfo;
///
/// let conn = render_primary_conninfo(
///     "postgres://replicator:secret@10.24.1.10:5432/postgres",
///     "negroni-1",
///     true,
///     "postgres",
/// );
/// assert!(conn.contains("host=10.24.1.10"));
/// assert!(conn.contains("port=5432"));
/// assert!(conn.contains("user=replicator"));
/// assert!(conn.contains("application_name=negroni-1"));
/// assert!(conn.contains("dbname=postgres"));
/// ```
pub fn render_primary_conninfo(
    upstream_conn: &str,
    self_member_name: &str,
    require_dbname: bool,
    fallback_dbname: &str,
) -> String {
    let escape_libpq_val = |v: &str| -> String {
        if v.is_empty()
            || v.chars()
                .any(|c| c.is_ascii_whitespace() || c == '\'' || c == '\\')
        {
            let inner = v.replace('\\', "\\\\").replace('\'', "\\'");
            format!("'{inner}'")
        } else {
            v.to_owned()
        }
    };

    if let Some(rest) = upstream_conn
        .strip_prefix("postgres://")
        .or_else(|| upstream_conn.strip_prefix("postgresql://"))
    {
        let (authority_and_path, query) = rest
            .split_once('?')
            .map_or((rest, ""), |(lhs, rhs)| (lhs, rhs));
        let (authority, path_db) = authority_and_path
            .split_once('/')
            .map_or((authority_and_path, ""), |(a, p)| (a, p));
        let (userinfo, hostport) = authority
            .rsplit_once('@')
            .map_or((None, authority), |(u, h)| (Some(u), h));

        let (host, port) = if let Some(bracketed) = hostport.strip_prefix('[') {
            if let Some((ipv6, after)) = bracketed.split_once(']') {
                let port = after.strip_prefix(':').unwrap_or("5432");
                (ipv6, port)
            } else {
                (hostport, "5432")
            }
        } else if let Some((h, p)) = hostport.rsplit_once(':') {
            (h, p)
        } else {
            (hostport, "5432")
        };

        let mut parts = Vec::new();
        if !host.is_empty() {
            parts.push(format!("host={}", escape_libpq_val(host)));
        }
        if !port.is_empty() {
            parts.push(format!("port={}", escape_libpq_val(port)));
        }
        if let Some(ui) = userinfo {
            let (user, pass) = ui.split_once(':').map_or((ui, None), |(u, p)| (u, Some(p)));
            if !user.is_empty() {
                parts.push(format!("user={}", escape_libpq_val(user)));
            }
            if let Some(pw) = pass
                && !pw.is_empty()
            {
                parts.push(format!("password={}", escape_libpq_val(pw)));
            }
        }

        let mut has_app_name = false;
        let mut has_dbname = false;
        if !path_db.is_empty() {
            has_dbname = true;
            parts.push(format!("dbname={}", escape_libpq_val(path_db)));
        }
        for pair in query.split('&').filter(|s| !s.is_empty()) {
            if let Some((k, v)) = pair.split_once('=') {
                if k == "application_name" {
                    has_app_name = true;
                }
                if k == "dbname" {
                    has_dbname = true;
                }
                parts.push(format!("{k}={}", escape_libpq_val(v)));
            }
        }
        if !has_app_name {
            parts.push(format!(
                "application_name={}",
                escape_libpq_val(self_member_name)
            ));
        }
        if require_dbname && !has_dbname {
            parts.push(format!("dbname={}", escape_libpq_val(fallback_dbname)));
        }
        return parts.join(" ");
    }

    // Already keyword=value format: ensure `application_name` and optional `dbname`.
    let mut out = upstream_conn.trim().to_owned();
    if !out.contains("application_name=") {
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(&format!(
            "application_name={}",
            escape_libpq_val(self_member_name)
        ));
    }
    if require_dbname && !out.contains("dbname=") {
        out.push_str(&format!(" dbname={}", escape_libpq_val(fallback_dbname)));
    }
    out
}

/// Sanitizes a Patroni member name into a valid PostgreSQL replication slot identifier
/// (`[a-z0-9_]`, max 63 bytes, matching Patroni `slot_name_from_member_name`).
pub fn member_name_to_slot_name(member_name: &str) -> CompactString {
    let mut sanitized = String::with_capacity(member_name.len().min(63));
    for ch in member_name.chars() {
        let mapped = if ch.is_ascii_uppercase() {
            ch.to_ascii_lowercase()
        } else if ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '_' {
            ch
        } else {
            '_'
        };
        if sanitized.len() < 63 {
            sanitized.push(mapped);
        }
    }
    if sanitized.is_empty() {
        CompactString::const_new("negroni_slot")
    } else {
        CompactString::from(sanitized)
    }
}

/// Runtime overlay parameters injected by the HA supervisor on top of `DaemonConfig`.
#[derive(Debug, Clone, Default)]
pub struct RuntimeGucOverlay {
    pub include_base_conf: bool,
    pub primary_conninfo: Option<String>,
    pub primary_slot_name: Option<CompactString>,
    pub synchronous_standby_names: Option<String>,
    pub synchronized_standby_slots: Option<String>,
}

fn json_to_guc_string(val: &JsonValue) -> String {
    match val {
        JsonValue::Bool(b) => if *b { "on" } else { "off" }.to_owned(),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::String(s) => s.clone(),
        other => other.to_string(),
    }
}

/// Renders the complete contents of `$CONFIG_DIR/postgresql.conf`, validating version-specific
/// GUCs against `major` (`PG 15..=18`).
pub fn render_postgresql_conf(
    cfg: &DaemonConfig,
    major: PgMajor,
    overlay: &RuntimeGucOverlay,
) -> Result<String, PgError> {
    let user_params = cfg.effective_pg_parameters();
    validate_version_specific_gucs(major, &user_params)?;

    let (listen_addr, listen_port) = parse_listen_host_port(&cfg.postgresql.listen);
    let has_logical_slots = cfg.dynamic.slots.values().any(|s| s.slot_type == "logical");

    let mut effective: BTreeMap<CompactString, String> = BTreeMap::new();
    effective.insert(CompactString::const_new("listen_addresses"), listen_addr);
    effective.insert(CompactString::const_new("port"), listen_port.to_string());
    effective.insert(
        CompactString::const_new("cluster_name"),
        cfg.scope.to_string(),
    );
    effective.insert(
        CompactString::const_new("wal_level"),
        if has_logical_slots {
            "logical".to_owned()
        } else {
            "replica".to_owned()
        },
    );
    effective.insert(CompactString::const_new("hot_standby"), "on".to_owned());
    effective.insert(CompactString::const_new("max_wal_senders"), "10".to_owned());
    effective.insert(
        CompactString::const_new("max_replication_slots"),
        "10".to_owned(),
    );
    effective.insert(
        CompactString::const_new("max_locks_per_transaction"),
        "64".to_owned(),
    );
    effective.insert(
        CompactString::const_new("wal_keep_size"),
        "128MB".to_owned(),
    );

    let rewind_enabled = cfg
        .dynamic
        .postgresql
        .use_pg_rewind
        .unwrap_or(cfg.postgresql.use_pg_rewind);
    if rewind_enabled {
        effective.insert(CompactString::const_new("wal_log_hints"), "on".to_owned());
    }

    for (k, v) in &user_params {
        if !v.is_null() {
            effective.insert(k.clone(), json_to_guc_string(v));
        }
    }

    // Ensure logical permanent slots force `wal_level = logical` even if user left `replica`.
    if has_logical_slots && effective.get("wal_level").map(String::as_str) == Some("replica") {
        effective.insert(CompactString::const_new("wal_level"), "logical".to_owned());
    }

    let caps = major.capabilities();
    let slotsync_requested = caps.native_failover_slots
        && (has_logical_slots
            || effective
                .get("sync_replication_slots")
                .is_some_and(|v| v == "on" || v == "true"));

    if let Some(ref raw_conninfo) = overlay.primary_conninfo {
        let rendered_conn =
            render_primary_conninfo(raw_conninfo, &cfg.name, slotsync_requested, "postgres");
        effective.insert(CompactString::const_new("primary_conninfo"), rendered_conn);
        effective.insert(
            CompactString::const_new("recovery_target_timeline"),
            "latest".to_owned(),
        );
    }

    if let Some(ref slot) = overlay.primary_slot_name {
        let valid_slot = member_name_to_slot_name(slot);
        effective.insert(
            CompactString::const_new("primary_slot_name"),
            valid_slot.to_string(),
        );
    }

    if let Some(ref sync_names) = overlay.synchronous_standby_names {
        effective.insert(
            CompactString::const_new("synchronous_standby_names"),
            sync_names.clone(),
        );
    }

    if caps.native_failover_slots
        && let Some(ref sync_slots) = overlay.synchronized_standby_slots
    {
        effective.insert(
            CompactString::const_new("synchronized_standby_slots"),
            sync_slots.clone(),
        );
    }

    let mut lines = Vec::with_capacity(effective.len() + 3);
    lines.push(MANAGED_HEADER.to_owned());
    if overlay.include_base_conf {
        lines.push("include 'postgresql.base.conf'".to_owned());
    }
    for (k, v) in &effective {
        lines.push(format_pg_conf_kv(k, v)?);
    }
    lines.push(String::new());
    Ok(lines.join("\n"))
}

/// Validates and atomically writes `postgresql.conf`, `pg_hba.conf`, and `pg_ident.conf`.
pub fn write_managed_pg_configs(
    cfg: &DaemonConfig,
    major: PgMajor,
    overlay: &RuntimeGucOverlay,
) -> Result<(), PgError> {
    let config_dir = cfg
        .postgresql
        .config_dir
        .as_deref()
        .unwrap_or(cfg.postgresql.data_dir.as_path());

    let has_base = ensure_postgresql_base_conf(config_dir)?;
    let mut eff_overlay = overlay.clone();
    eff_overlay.include_base_conf = overlay.include_base_conf || has_base;

    let pg_conf_text = render_postgresql_conf(cfg, major, &eff_overlay)?;
    let hba_lines = cfg.effective_pg_hba();
    if !hba_lines.is_empty() {
        validate_pg_hba(major, hba_lines)?;
    }

    let ident_lines = if !cfg.dynamic.postgresql.pg_ident.is_empty() {
        &cfg.dynamic.postgresql.pg_ident
    } else {
        &cfg.postgresql.pg_ident
    };
    if !ident_lines.is_empty() {
        validate_pg_ident(major, ident_lines)?;
    }

    atomic_write_file(
        &config_dir.join("postgresql.conf"),
        pg_conf_text.as_bytes(),
        Some(0o600),
    )?;

    if !hba_lines.is_empty() {
        let mut body = String::from(MANAGED_HEADER);
        body.push('\n');
        for line in hba_lines {
            body.push_str(line);
            body.push('\n');
        }
        atomic_write_file(
            &config_dir.join("pg_hba.conf"),
            body.as_bytes(),
            Some(0o600),
        )?;
    }

    if !ident_lines.is_empty() {
        let mut body = String::from(MANAGED_HEADER);
        body.push('\n');
        for line in ident_lines {
            body.push_str(line);
            body.push('\n');
        }
        atomic_write_file(
            &config_dir.join("pg_ident.conf"),
            body.as_bytes(),
            Some(0o600),
        )?;
    }

    Ok(())
}

fn escape_pgpass_field(field: &str) -> String {
    let mut out = String::with_capacity(field.len());
    for ch in field.chars() {
        if ch == '\\' || ch == ':' {
            out.push('\\');
        }
        out.push(ch);
    }
    out
}

/// Atomically writes a `0600` `.pgpass` file for `pg_basebackup` / `pg_rewind` subprocesses.
pub fn write_pgpass_file(
    pgpass_path: &Path,
    host: &str,
    port: &str,
    database: &str,
    username: &str,
    password: &str,
) -> Result<(), PgError> {
    let line = format!(
        "{}:{}:{}:{}:{}\n",
        escape_pgpass_field(host),
        escape_pgpass_field(port),
        escape_pgpass_field(database),
        escape_pgpass_field(username),
        escape_pgpass_field(password),
    );
    atomic_write_file(pgpass_path, line.as_bytes(), Some(0o600))
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
mod tests {
    use negroni_config::parse_and_validate_with_env;

    use super::*;

    #[test]
    fn preserves_existing_postgresql_conf_into_base_conf_and_injects_pg17_slotsync_dbname() {
        let tmp_dir =
            std::env::temp_dir().join(format!("negroni-cfg-writer-{}", std::process::id()));
        let _ = fs::remove_dir_all(&tmp_dir);
        fs::create_dir_all(&tmp_dir).unwrap();

        // Simulate pre-existing DBA postgresql.conf
        fs::write(
            tmp_dir.join("postgresql.conf"),
            "shared_preload_libraries = 'pg_stat_statements'\n",
        )
        .unwrap();

        let yaml = format!(
            r#"
scope: payments
name: pg-node-1
watchdog:
  mode: off
bootstrap:
  dcs:
    slots:
      cdc_slot:
        type: logical
        database: payments
        plugin: pgoutput
postgresql:
  listen: 0.0.0.0:5432
  data_dir: {}
  pg_hba:
    - local all postgres peer
    - hostssl all /^app_.+$/ 10.0.0.0/8 scram-sha-256
"#,
            tmp_dir.display()
        );
        let empty_env: [(&str, &str); 0] = [];
        let cfg = parse_and_validate_with_env(&yaml, "test.yml", empty_env).unwrap();

        let overlay = RuntimeGucOverlay {
            include_base_conf: false,
            primary_conninfo: Some("postgres://replicator:pw@10.0.0.1:5432".to_owned()),
            primary_slot_name: Some(CompactString::from("pg-node-1")),
            synchronous_standby_names: None,
            synchronized_standby_slots: Some("pg_node_2".to_owned()),
        };

        write_managed_pg_configs(&cfg, PgMajor::V17, &overlay).unwrap();

        assert!(tmp_dir.join("postgresql.base.conf").exists());
        let rendered = fs::read_to_string(tmp_dir.join("postgresql.conf")).unwrap();
        assert!(rendered.contains("include 'postgresql.base.conf'"));
        assert!(rendered.contains("wal_level = 'logical'"));
        assert!(rendered.contains("dbname=postgres"));
        assert!(rendered.contains("primary_slot_name = 'pg_node_1'"));
        assert!(rendered.contains("synchronized_standby_slots = 'pg_node_2'"));

        #[cfg(unix)]
        {
            let mode = fs::metadata(tmp_dir.join("postgresql.conf"))
                .unwrap()
                .permissions()
                .mode()
                & 0o777;
            assert_eq!(mode, 0o600);
        }

        let _ = fs::remove_dir_all(&tmp_dir);
    }

    #[test]
    fn escapes_colons_and_backslashes_in_pgpass() {
        let tmp = std::env::temp_dir().join(format!("negroni-pgpass-{}", std::process::id()));
        write_pgpass_file(&tmp, "*", "5432", "*", "repl", r"p:w\secret").unwrap();
        let raw = fs::read_to_string(&tmp).unwrap();
        assert_eq!(raw, "*:5432:*:repl:p\\:w\\\\secret\n");
        let _ = fs::remove_file(&tmp);
    }
}
